<?php declare(strict_types=1);use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;$years=[];foreach($rows as$r)$years[]=substr((string)$r['report_date'],0,4);$years=array_values(array_unique($years));sort($years);$yearOptions=['all'=>'Все годы','none'=>'Без года'];foreach($years as$year)$yearOptions[$year]=$year;$query=Yii::$app->request->get();$rub=static fn(int$c)=>number_format($c/100,2,',',' ').' ₽';ViewSupport::begin($this,'Расчёты ОТиЗ',$identity,'otiz','wide');?>
<main class="fm2-otiz fm2-otiz-page fm2-otiz-v2-page"><section class="fm2-otiz-surface fm2-otiz-overview-surface"><div class="fm2-otiz-tabs-surface"><?=$this->render('_otiz-nav',['current'=>'payments'])?></div><div class="fm2-otiz-v2-header"><header class="fm2-page-header"><div><h1>Расчёты ОТиЗ</h1><p>Единый реестр черновиков, обязательств и истории выплат</p></div></header><form class="fm2-otiz-v2-new" method="post" action="/pilot/otiz/calculations"><input type="hidden" name="_csrf" value="<?=Html::encode($csrf)?>"><input type="hidden" name="operationId" value="<?=ViewSupport::uuid()?>"><label class="shlz-field"><span class="shlz-field__label">Расчётная дата</span><span class="shlz-field__control"><input class="shlz-input" type="date" name="reportDate" required></span></label><button class="shlz-button shlz-button--primary">Новый расчёт</button></form></div></section>
<?php if(($query['error']??'')==='empty'):?><p class="shlz-alert" role="status">Новых работ для расчёта нет. <a class="shlz-link" href="/pilot/otiz/payments?filter=waiting&amp;year=all">Перейти к ожидающим выплатам</a>.</p><?php endif?>
<section class="fm2-otiz-surface fm2-otiz-v2-register-surface"><nav class="fm2-otiz-v2-list-tabs" aria-label="Фильтры расчётов"><?php foreach(['waiting'=>'Ожидают выплаты','drafts'=>'Черновики','history'=>'История','all'=>'Все']as$key=>$label):$active=(string)($query['filter']??'waiting')===$key;?><a class="<?=$active?'is-active':''?>" href="?filter=<?=$key?>&amp;year=<?=Html::encode((string)($query['year']??'all'))?>"<?=$active?' aria-current="page"':''?>><?=$label?></a><?php endforeach?></nav><form class="fm2-otiz-v2-toolbar fm2-otiz-v2-toolbar--register" method="get" action="/pilot/otiz/payments"><input type="hidden" name="filter" value="<?=Html::encode((string)($query['filter']??'waiting'))?>"><?=ViewSupport::choice('year',(string)($query['year']??'all'),$yearOptions,'Год расчёта')?><button class="shlz-button shlz-button--secondary">Показать</button></form><?php if($rows===[]):?><p class="fm2-otiz-v2-empty">В этой группе пока нет расчётов. Измените фильтр или подготовьте новый черновик.</p><?php endif?>
<div class="shlz-table-wrap fm2-otiz-v2-table-wrap" data-mobile-strategy="contained-scroll" tabindex="0" aria-label="Реестр расчётов ОТиЗ"><table class="shlz-table fm2-otiz-v2-register-table"><thead class="shlz-table__head"><tr class="shlz-table__row"><?php foreach(['Расчёт','Дата','Автор','Статус','Сумма','Выплачено','Остаток / причина']as$heading):?><th class="shlz-table__cell" scope="col"><?=$heading?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as$r):$p=is_array($r['projection']??null)?$r['projection']:json_decode((string)$r['projection_json'],true);$sum=(int)($p['totalCents']??0);$reason=(string)($r['blocking_reason']??$p['blockingReason']??'');$status=(string)$r['status'];$state=match($status){'draft'=>'Черновик','accepted'=>'Утверждён','cancelled'=>'Отменён',default=>'Нет данных'};$statusClass=match($status){'accepted'=>'shlz-status--bright-green','cancelled'=>'shlz-status--neutral',default=>'shlz-status--yellow'};$amountLabel=match($status){'draft'=>'Предварительно к выплате','accepted'=>'Утверждено к выплате',default=>'Сохранённая сумма'};?><tr class="shlz-table__row"><td class="shlz-table__cell"><a class="shlz-link" href="/pilot/otiz/calculations/<?=(int)$r['id']?>"><strong>Расчёт #<?=(int)$r['id']?></strong></a></td><td class="shlz-table__cell"><?=Html::encode((string)$r['report_date'])?></td><td class="shlz-table__cell"><?=Html::encode((string)($r['author_name']??$r['actor_user_id']??'Нет данных'))?></td><td class="shlz-table__cell"><span class="shlz-status <?=$statusClass?>"><?=$state?></span></td><td class="shlz-table__cell shlz-table__cell--numeric"><span class="fm2-otiz-v2-cell-label"><?=$amountLabel?></span><strong><?=$rub($sum)?></strong></td><td class="shlz-table__cell shlz-table__cell--numeric"><?=$rub((int)($r['paid_cents']??0))?></td><td class="shlz-table__cell shlz-table__cell--numeric"><strong><?=$rub(max(0,$sum-(int)($r['paid_cents']??0)))?></strong><?php if($reason!==''):?><small><?=Html::encode($reason)?></small><?php elseif($status==='cancelled'):?><small>Расчёт отменён</small><?php endif?></td></tr><?php endforeach?></tbody></table></div><?=ViewSupport::pagination('/pilot/otiz/payments',$page,$pages,$total,$pageSize,['filter'=>$query['filter']??'waiting','year'=>$query['year']??'all'],'Страницы расчётов ОТиЗ')?></section></main><?php ViewSupport::end($this);?>
